// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContestProblem) predicate.ContestProblem {
	return predicate.ContestProblem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContestProblem) predicate.ContestProblem {
	return predicate.ContestProblem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContestProblem) predicate.ContestProblem {
	return predicate.ContestProblem(sql.NotPredicates(p))
}
